-- Sanal Türkiye — PostgreSQL + PostGIS şeması (scripts/postgres-aktar.js ile SQLite şemasından üretildi)
CREATE EXTENSION IF NOT EXISTS postgis;
BEGIN;
CREATE TABLE IF NOT EXISTS "adaylar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "secim_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "manifesto" TEXT NOT NULL,
  "vaatler" TEXT NOT NULL DEFAULT '[]',
  "butce" BIGINT,
  "durum" TEXT NOT NULL DEFAULT 'AKTIF',
  "created_at" BIGINT NOT NULL,
  "makam" TEXT NOT NULL DEFAULT 'MUHTAR',
  PRIMARY KEY ("id"),
  UNIQUE ("secim_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "afetler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "plaka" TEXT NOT NULL,
  "tur" TEXT NOT NULL,
  "olcum" TEXT,
  "etkilenen" BIGINT NOT NULL DEFAULT 0,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "audit_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "idempotency_key" TEXT,
  "actor_id" BIGINT,
  "action" TEXT NOT NULL,
  "entity" TEXT,
  "before_json" TEXT,
  "after_json" TEXT,
  "region_id" BIGINT,
  "public" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("idempotency_key")
);
CREATE TABLE IF NOT EXISTS "ayarlar" (
  "anahtar" TEXT,
  "deger" TEXT NOT NULL,
  PRIMARY KEY ("anahtar")
);
CREATE TABLE IF NOT EXISTS "belediye_katki_gunleri" (
  "region_id" BIGINT,
  "gun" BIGINT,
  "tutar" BIGINT NOT NULL,
  PRIMARY KEY ("region_id", "gun")
);
CREATE TABLE IF NOT EXISTS "belediye_uyeleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "region_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "makam" TEXT NOT NULL,
  "secim_id" BIGINT NOT NULL,
  "aday_id" BIGINT NOT NULL,
  "baslangic" BIGINT NOT NULL,
  "bitis" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "bids" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "listing_id" BIGINT NOT NULL,
  "buyer_id" BIGINT NOT NULL,
  "amount" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'ACTIVE',
  "created_at" BIGINT NOT NULL,
  "updated_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "crops" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "crop_type" TEXT NOT NULL,
  "planted_at" BIGINT NOT NULL,
  "ready_at" BIGINT NOT NULL,
  "waterings" BIGINT NOT NULL DEFAULT 0,
  "last_watered_at" BIGINT,
  "status" TEXT NOT NULL DEFAULT 'GROWING',
  "harvested_qty" BIGINT,
  "don" BIGINT NOT NULL DEFAULT 0,
  "yagmur_at" BIGINT,
  "mevsim" TEXT,
  "afet_kati" DOUBLE PRECISION NOT NULL DEFAULT 1,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "eposta_tokenlari" (
  "token_hash" TEXT,
  "user_id" BIGINT NOT NULL,
  "tur" TEXT NOT NULL,
  "expires_at" TEXT NOT NULL,
  "kullanildi_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("token_hash")
);
CREATE TABLE IF NOT EXISTS "giden_postalar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "alici" TEXT NOT NULL,
  "konu" TEXT NOT NULL,
  "govde" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "gorev_vaatleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "uye_id" BIGINT NOT NULL,
  "sira" BIGINT NOT NULL,
  "metin" TEXT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'BEKLIYOR',
  "aciklama" TEXT,
  "updated_at" BIGINT NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("uye_id", "sira")
);
CREATE TABLE IF NOT EXISTS "gorevden_alma" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "region_id" BIGINT NOT NULL,
  "makam" TEXT NOT NULL,
  "hedef_id" BIGINT NOT NULL,
  "baslatan_id" BIGINT NOT NULL,
  "gerekce" TEXT NOT NULL,
  "esik" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'ACIK',
  "bitis" BIGINT NOT NULL,
  "created_at" BIGINT NOT NULL,
  "kapandi_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "gorevden_alma_imzalar" (
  "dilekce_id" BIGINT,
  "user_id" BIGINT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("dilekce_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "hava_durumu" (
  "plaka" TEXT,
  "sicaklik" DOUBLE PRECISION,
  "yagis" DOUBLE PRECISION,
  "kod" BIGINT,
  "ruzgar" DOUBLE PRECISION,
  "gunduz" BIGINT,
  "guncellendi" BIGINT NOT NULL,
  PRIMARY KEY ("plaka")
);
CREATE TABLE IF NOT EXISTS "il_talep" (
  "gun" TEXT,
  "plaka" TEXT,
  "urun" TEXT,
  "satilan" BIGINT NOT NULL,
  PRIMARY KEY ("gun", "plaka", "urun")
);
CREATE TABLE IF NOT EXISTS "imar_karolari" (
  "kx" BIGINT,
  "ky" BIGINT,
  "surum" BIGINT NOT NULL,
  "kod" TEXT NOT NULL,
  "ilce" TEXT NOT NULL,
  "kaynak" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  PRIMARY KEY ("kx", "ky")
);
CREATE TABLE IF NOT EXISTS "inventory_ledger" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "item_id" TEXT NOT NULL,
  "delta" BIGINT NOT NULL,
  "reason" TEXT NOT NULL,
  "tx_group" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "itirazlar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "secim_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "sebep" TEXT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'INCELEMEDE',
  "yanit" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("secim_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "kiralar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "sahip_id" BIGINT NOT NULL,
  "kiraci_id" BIGINT,
  "gunluk" BIGINT NOT NULL,
  "gun" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'TEKLIF',
  "created_at" BIGINT NOT NULL,
  "baslangic" BIGINT,
  "bitis" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "koleksiyon" (
  "user_id" BIGINT,
  "simge" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "simge")
);
CREATE TABLE IF NOT EXISTS "kooperatif_uyeleri" (
  "koop_id" BIGINT,
  "user_id" BIGINT,
  "katilim" BIGINT NOT NULL,
  PRIMARY KEY ("koop_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "kooperatifler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "il_id" BIGINT NOT NULL,
  "ad" TEXT NOT NULL,
  "aciklama" TEXT,
  "baskan_id" BIGINT NOT NULL,
  "created_at" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'AKTIF',
  PRIMARY KEY ("id"),
  UNIQUE ("il_id", "ad")
);
CREATE TABLE IF NOT EXISTS "kozmetikler" (
  "user_id" BIGINT,
  "kod" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "kod")
);
CREATE TABLE IF NOT EXISTS "listings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "seller_id" BIGINT NOT NULL,
  "asking_price" BIGINT NOT NULL,
  "listing_currency" TEXT NOT NULL DEFAULT 'AKCE',
  "asset_snapshot" TEXT NOT NULL,
  "fee_rate" DOUBLE PRECISION NOT NULL,
  "buyer_condition" TEXT NOT NULL DEFAULT 'HERKES',
  "status" TEXT NOT NULL DEFAULT 'ACTIVE',
  "created_at" BIGINT NOT NULL,
  "expires_at" BIGINT NOT NULL,
  "closed_at" BIGINT,
  "version" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "mahalle_duyurulari" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "region_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "metin" TEXT NOT NULL,
  "created_at" BIGINT NOT NULL,
  "gizlendi" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "moderasyon_islemleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "tur" TEXT NOT NULL,
  "hedef" TEXT NOT NULL,
  "gerekce" TEXT NOT NULL,
  "sikayet_id" BIGINT,
  "durum" TEXT NOT NULL DEFAULT 'ONAY_BEKLIYOR',
  "oneren_id" BIGINT NOT NULL,
  "onaylayan_id" BIGINT,
  "created_at" BIGINT NOT NULL,
  "karar_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "muhtarlar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "region_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "secim_id" BIGINT NOT NULL,
  "aday_id" BIGINT NOT NULL,
  "baslangic" BIGINT NOT NULL,
  "bitis" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "notifications" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "text" TEXT NOT NULL,
  "link" TEXT,
  "read_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "npc_demand" (
  "day" TEXT,
  "item_id" TEXT,
  "sold" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("day", "item_id")
);
CREATE TABLE IF NOT EXISTS "ortaklar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "sahip_id" BIGINT NOT NULL,
  "ortak_id" BIGINT NOT NULL,
  "pay" DOUBLE PRECISION NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'DAVET',
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "parcel_ownership" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "start_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "end_at" TEXT,
  "reason" TEXT NOT NULL,
  "price" DOUBLE PRECISION,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "parcels" (
  "id" TEXT,
  "region_id" BIGINT NOT NULL,
  "ilce_id" BIGINT NOT NULL,
  "il_id" BIGINT NOT NULL,
  "district_code" TEXT NOT NULL,
  "area_m2" BIGINT NOT NULL,
  "zoning_type" TEXT NOT NULL,
  "zoning_source" TEXT NOT NULL,
  "centroid_lon" DOUBLE PRECISION NOT NULL,
  "centroid_lat" DOUBLE PRECISION NOT NULL,
  "grid_x" BIGINT NOT NULL,
  "grid_y" BIGINT NOT NULL,
  "owner_user_id" BIGINT,
  "status" TEXT NOT NULL DEFAULT 'ACTIVE',
  "geom_version" TEXT NOT NULL DEFAULT 'z20-v1',
  "version" BIGINT NOT NULL DEFAULT 0,
  "acquired_at" TEXT,
  PRIMARY KEY ("id"),
  "geom" geometry(Polygon, 4326),
  "merkez" geometry(Point, 4326)
);
CREATE TABLE IF NOT EXISTS "proje_oylari" (
  "proje_id" BIGINT,
  "user_id" BIGINT,
  "oy" TEXT NOT NULL,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("proje_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "projeler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "region_id" BIGINT NOT NULL,
  "hedef_region_id" BIGINT NOT NULL,
  "tur" TEXT NOT NULL,
  "maliyet" BIGINT NOT NULL,
  "gerekce" TEXT NOT NULL,
  "talep_id" BIGINT,
  "teklif_eden_id" BIGINT NOT NULL,
  "durum" TEXT NOT NULL,
  "nitelikli" BIGINT NOT NULL DEFAULT 0,
  "nitelikli_sebep" TEXT,
  "oylama_bitis" BIGINT NOT NULL,
  "yapim_bas" BIGINT,
  "yapim_bitis" BIGINT,
  "karar_json" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "push_abonelikleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "endpoint" TEXT NOT NULL,
  "p256dh" TEXT NOT NULL,
  "auth" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("endpoint")
);
CREATE TABLE IF NOT EXISTS "quest_progress" (
  "user_id" BIGINT,
  "quest_code" TEXT,
  "completed_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("user_id", "quest_code")
);
CREATE TABLE IF NOT EXISTS "referandum_imzalar" (
  "ref_id" BIGINT,
  "user_id" BIGINT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("ref_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "referandum_katilim" (
  "ref_id" BIGINT,
  "user_id" BIGINT,
  PRIMARY KEY ("ref_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "referandum_oylari" (
  "makbuz_ozeti" TEXT,
  "ref_id" BIGINT NOT NULL,
  "oy" TEXT NOT NULL,
  PRIMARY KEY ("makbuz_ozeti")
);
CREATE TABLE IF NOT EXISTS "referandumlar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "region_id" BIGINT NOT NULL,
  "baslatan_id" BIGINT NOT NULL,
  "soru" TEXT NOT NULL,
  "aciklama" TEXT,
  "durum" TEXT NOT NULL DEFAULT 'IMZA',
  "esik" BIGINT NOT NULL,
  "kutuk" BIGINT,
  "created_at" BIGINT NOT NULL,
  "oylama_bas" BIGINT,
  "oylama_bitis" BIGINT,
  "sonuc_json" TEXT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "regions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parent_id" BIGINT,
  "type" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "plaka" TEXT,
  "center_lon" DOUBLE PRECISION,
  "center_lat" DOUBLE PRECISION,
  "bbox" TEXT,
  "place_class" TEXT,
  "source_idx" BIGINT,
  "attractiveness" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "playable" BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY ("id"),
  UNIQUE ("code"),
  "merkez" geometry(Point, 4326)
);
CREATE TABLE IF NOT EXISTS "rozetler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "kod" TEXT NOT NULL,
  "ad" TEXT NOT NULL,
  "ikon" TEXT NOT NULL,
  "aciklama" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("user_id", "kod")
);
CREATE TABLE IF NOT EXISTS "secim_katilim" (
  "secim_id" BIGINT,
  "user_id" BIGINT,
  "gun" TEXT NOT NULL,
  "cihaz_ozeti" TEXT NOT NULL,
  PRIMARY KEY ("secim_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "secim_oylari" (
  "makbuz_ozeti" TEXT,
  "secim_id" BIGINT NOT NULL,
  "aday_id" BIGINT NOT NULL,
  "makam" TEXT NOT NULL DEFAULT 'MUHTAR',
  PRIMARY KEY ("makbuz_ozeti")
);
CREATE TABLE IF NOT EXISTS "secimler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "region_id" BIGINT NOT NULL,
  "tur" TEXT NOT NULL DEFAULT 'MUHTAR',
  "asama" TEXT NOT NULL,
  "duyuru_at" BIGINT NOT NULL,
  "adaylik_at" BIGINT NOT NULL,
  "kampanya_at" BIGINT NOT NULL,
  "oylama_at" BIGINT NOT NULL,
  "itiraz_at" BIGINT NOT NULL,
  "bitis_at" BIGINT NOT NULL,
  "sonuc_json" TEXT,
  "ozet_hash" TEXT,
  "kazanan_aday_id" BIGINT,
  "iptal_sebebi" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "secmen_kutugu" (
  "secim_id" BIGINT,
  "user_id" BIGINT,
  PRIMARY KEY ("secim_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "sessions" (
  "token_hash" TEXT,
  "user_id" BIGINT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "expires_at" TEXT NOT NULL,
  "ikinci_adim" BIGINT NOT NULL DEFAULT 1,
  "deneme" BIGINT NOT NULL DEFAULT 0,
  "tarayici" TEXT,
  "ip_ozet" TEXT,
  "son_gorulme" TEXT,
  PRIMARY KEY ("token_hash")
);
CREATE TABLE IF NOT EXISTS "sevkiyatlar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "urun" TEXT NOT NULL,
  "miktar" BIGINT NOT NULL,
  "kaynak_plaka" TEXT NOT NULL,
  "hedef_plaka" TEXT NOT NULL,
  "mod" TEXT NOT NULL,
  "km" DOUBLE PRECISION NOT NULL,
  "maliyet" DOUBLE PRECISION NOT NULL,
  "cikis" BIGINT NOT NULL,
  "varis" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'YOLDA',
  "gelir" DOUBLE PRECISION,
  "notlar" TEXT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "sezon_sonuclari" (
  "sezon" BIGINT,
  "il_id" BIGINT,
  "puan" DOUBLE PRECISION NOT NULL,
  "oyuncu" BIGINT NOT NULL,
  "lig_puani" DOUBLE PRECISION NOT NULL,
  "sira" BIGINT NOT NULL,
  PRIMARY KEY ("sezon", "il_id")
);
CREATE TABLE IF NOT EXISTS "sikayetler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "sikayetci_id" BIGINT NOT NULL,
  "hedef_tur" TEXT NOT NULL,
  "hedef_id" TEXT NOT NULL,
  "sebep" TEXT NOT NULL,
  "aciklama" TEXT,
  "durum" TEXT NOT NULL DEFAULT 'ACIK',
  "karar" TEXT,
  "karar_veren" BIGINT,
  "on_tarama" TEXT,
  "created_at" BIGINT NOT NULL,
  "kapandi_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "sohbet_mesajlari" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "kanal" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "metin" TEXT NOT NULL,
  "on_tarama" TEXT,
  "gizlendi" BIGINT NOT NULL DEFAULT 0,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "structures" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "owner_user_id" BIGINT NOT NULL,
  "type" TEXT NOT NULL,
  "level" BIGINT NOT NULL DEFAULT 1,
  "health" BIGINT NOT NULL DEFAULT 100,
  "footprint_m2" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "floor_area_m2" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL,
  "started_at" BIGINT NOT NULL,
  "completes_at" BIGINT NOT NULL,
  "completed_at" BIGINT,
  "bakim_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "talepler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "mahalle_id" BIGINT NOT NULL,
  "ilce_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "tur" TEXT NOT NULL,
  "aciklama" TEXT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'ACIK',
  "proje_id" BIGINT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "trades" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "listing_id" BIGINT NOT NULL,
  "parcel_id" TEXT NOT NULL,
  "seller_id" BIGINT NOT NULL,
  "buyer_id" BIGINT NOT NULL,
  "price" BIGINT NOT NULL,
  "fee" BIGINT NOT NULL,
  "via" TEXT NOT NULL,
  "asset_snapshot" TEXT NOT NULL,
  "flags" TEXT NOT NULL DEFAULT '[]',
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("listing_id")
);
CREATE TABLE IF NOT EXISTS "uretimler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "parcel_id" TEXT NOT NULL,
  "structure_id" BIGINT NOT NULL,
  "recete" TEXT NOT NULL,
  "parti" BIGINT NOT NULL,
  "cikti" BIGINT NOT NULL,
  "baslangic" BIGINT NOT NULL,
  "bitis" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'URETIMDE',
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "urun_emirleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "urun" TEXT NOT NULL,
  "yon" TEXT NOT NULL,
  "fiyat" DOUBLE PRECISION NOT NULL,
  "miktar" BIGINT NOT NULL,
  "kalan" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'ACIK',
  "created_at" BIGINT NOT NULL,
  "expires_at" BIGINT NOT NULL,
  "closed_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "urun_islemleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "urun" TEXT NOT NULL,
  "alis_emri" BIGINT NOT NULL,
  "satis_emri" BIGINT NOT NULL,
  "alici_id" BIGINT NOT NULL,
  "satici_id" BIGINT NOT NULL,
  "fiyat" DOUBLE PRECISION NOT NULL,
  "miktar" BIGINT NOT NULL,
  "ucret" DOUBLE PRECISION NOT NULL,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "email" TEXT,
  "password_hash" TEXT,
  "display_name" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'ACTIVE',
  "trust_level" BIGINT NOT NULL DEFAULT 0,
  "is_npc" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "email_dogrulandi_at" TEXT,
  "totp_sir" TEXT,
  "totp_aktif" BIGINT NOT NULL DEFAULT 0,
  "totp_son_adim" BIGINT NOT NULL DEFAULT 0,
  "kurtarma_kodlari" TEXT,
  "dogum_yili" BIGINT,
  "rol" TEXT NOT NULL DEFAULT 'OYUNCU',
  "silindi_at" TEXT,
  "ayarlar" TEXT NOT NULL DEFAULT '{}',
  "bozulma_gun" BIGINT,
  "memleket_plaka" TEXT,
  "memleket_at" BIGINT,
  "meslek" TEXT,
  "meslek_xp" BIGINT NOT NULL DEFAULT 0,
  "meslek_at" BIGINT,
  "kozmetik" TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY ("id"),
  UNIQUE ("email")
);
CREATE TABLE IF NOT EXISTS "vaat_takip" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "muhtar_id" BIGINT NOT NULL,
  "sira" BIGINT NOT NULL,
  "metin" TEXT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'BEKLIYOR',
  "aciklama" TEXT,
  "updated_at" BIGINT NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("muhtar_id", "sira")
);
CREATE TABLE IF NOT EXISTS "visits" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "visitor_id" BIGINT NOT NULL,
  "parcel_id" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "wallet_ledger" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "account" TEXT NOT NULL,
  "user_id" BIGINT,
  "unit" TEXT NOT NULL DEFAULT 'AKCE',
  "debit" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "credit" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "tx_group" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "yasal_onaylar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "belge" TEXT NOT NULL,
  "surum" TEXT NOT NULL,
  "onay" BIGINT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "yerler" (
  "id" TEXT,
